// app/api/admin/promotions/[id]/archive/route.ts — Archive a promotion (soft delete)
import { NextResponse } from "next/server";
import { requireAdminInvisibility } from "@/app/lib/auth";
import { PromotionService } from "@/src/services/promotion.service";

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  const auth = await requireAdminInvisibility(request);
  if (auth.errorResponse) return auth.errorResponse;

  const resolvedParams = await params;
  const id = Number.parseInt((resolvedParams?.id || "").trim(), 10);
  if (!Number.isInteger(id) || id <= 0) {
    return NextResponse.json(
      { success: false, error: "A valid promotion id is required" },
      { status: 400 }
    );
  }

  try {
    const archived = await PromotionService.archivePromotion(id);
    if (!archived) {
      return NextResponse.json(
        { success: false, error: "Promotion not found or already archived" },
        { status: 404 }
      );
    }
    return NextResponse.json({ success: true, archived: true });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err?.message || "Failed to archive promotion" },
      { status: 500 }
    );
  }
}

