"use client";

import React, { useCallback, useEffect, useState } from "react";
import { Archive, Loader2, RefreshCw } from "lucide-react";
import { useToast } from "@/app/components/Toast";

interface PromotionRow {
  id: number;
  code: string;
  title: string;
  discount_type: "PERCENTAGE" | "FIXED";
  discount_value: number;
  used_count: number;
  usage_limit?: number | null;
  expires_at?: string | null;
  is_active: boolean;
  archived_at?: string | null;
}

export function AdminPromotionsView() {
  const toast = useToast();
  const [promotions, setPromotions] = useState<PromotionRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [archivingId, setArchivingId] = useState<number | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/promotions", { cache: "no-store", credentials: "include" });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || `HTTP ${res.status}`);
      setPromotions(data.promotions || []);
    } catch (err: any) {
      setError(err?.message || "Failed to load promotions");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const archive = async (promo: PromotionRow) => {
    if (!window.confirm(`Archive promotion ${promo.code}? It will stop working at checkout.`)) return;
    setArchivingId(promo.id);
    try {
      const res = await fetch(`/api/admin/promotions/${promo.id}/archive`, {
        method: "POST",
        credentials: "include",
      });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || `HTTP ${res.status}`);
      toast.success(`Promotion ${promo.code} archived`);
      await load();
    } catch (err: any) {
      toast.error(err?.message || "Failed to archive promotion");
    } finally {
      setArchivingId(null);
    }
  };

  return (
    <div className="space-y-4 p-4">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold">Promotions</h1>
        <button
          type="button"
          onClick={load}
          disabled={loading}
          className="inline-flex items-center gap-2 rounded-md border px-3 py-1.5 text-sm"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} /> Refresh
        </button>
      </div>

      {error && <p className="text-sm text-red-500">{error}</p>}

      <div className="overflow-x-auto rounded-lg border">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b">
              <th className="p-3">Code</th>
              <th className="p-3">Title</th>
              <th className="p-3">Discount</th>
              <th className="p-3">Used</th>
              <th className="p-3">Status</th>
              <th className="p-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {promotions.length === 0 && !loading && (
              <tr>
                <td colSpan={6} className="p-6 text-center opacity-70">
                  No promotions found.
                </td>
              </tr>
            )}
            {promotions.map((p) => (
              <tr key={p.id} className="border-b last:border-0">
                <td className="p-3 font-mono">{p.code}</td>
                <td className="p-3">{p.title}</td>
                <td className="p-3">
                  {p.discount_type === "PERCENTAGE" ? `${p.discount_value}%` : `₱${p.discount_value.toFixed(2)}`}
                </td>
                <td className="p-3">
                  {p.used_count}
                  {p.usage_limit ? ` / ${p.usage_limit}` : ""}
                </td>
                <td className="p-3">{p.archived_at ? "Archived" : p.is_active ? "Active" : "Inactive"}</td>
                <td className="p-3 text-right">
                  {!p.archived_at && (
                    <button
                      type="button"
                      onClick={() => archive(p)}
                      disabled={archivingId === p.id}
                      className="inline-flex items-center gap-1.5 rounded-md border px-3 py-1.5 text-xs disabled:opacity-50"
                    >
                      {archivingId === p.id ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <Archive className="h-3.5 w-3.5" />
                      )}
                      Archive
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
